import { getterTree, mutationTree, actionTree } from 'typed-vuex'

export const namespaced = true

const STORAGE_KEY = 'codx-teams-store'

// ── Data type factories ───────────────────────────────────────────────────────

export const createTeam = (overrides = {}) => ({
  id: crypto.randomUUID(),
  name: '',
  description: '',
  icon: null,
  color: '#6366f1',
  createdAt: new Date().toISOString(),
  updatedAt: new Date().toISOString(),
  categories: [],
  members: [],
  directMessages: {},
  ...overrides
})

export const createCategory = (overrides = {}) => ({
  id: crypto.randomUUID(),
  name: 'General',
  collapsed: false,
  channels: [],
  ...overrides
})

export const createChannel = (overrides = {}) => ({
  id: crypto.randomUUID(),
  name: '',
  description: '',
  mode: 'topic',
  chatId: null,
  categoryId: null,
  unread: 0,
  pinned: false,
  createdAt: new Date().toISOString(),
  ...overrides
})

export const createMember = (overrides = {}) => ({
  id: crypto.randomUUID(),
  username: '',
  role: 'member',
  status: 'online',
  joinedAt: new Date().toISOString(),
  ...overrides
})

// ── Persistence helpers ───────────────────────────────────────────────────────

function persist(state) {
  try {
    localStorage.setItem(STORAGE_KEY, JSON.stringify({
      teams: state.teams,
      activeTeamId: state.activeTeamId,
      activeChannelId: state.activeChannelId,
      activeDmMemberId: state.activeDmMemberId
